  // typed text -> "dd.mm.yyyy" (day first), or null. Accepts 31.12.2026, 31/12/26, 31-12-2026, 2026-12-31,
  // and a range (the last date counts).
  parseDate(text) {
    let t = String(text == null ? "" : text).trim();
    if (!t) return null;
    const parts = t.split(/\s+[-–—]\s+|\s+עד\s+/).filter(x => x.trim());
    if (parts.length) t = parts[parts.length - 1].trim();
    let y, m, d, mt;
    if ((mt = /^(\d{4})-(\d{2})-(\d{2})/.exec(t))) { y = +mt[1]; m = +mt[2]; d = +mt[3]; }
    else if ((mt = /^(\d{1,2})\s*[./\-]\s*(\d{1,2})\s*[./\-]\s*(\d{4}|\d{2})$/.exec(t))) { d = +mt[1]; m = +mt[2]; y = +mt[3]; if (mt[3].length === 2) y += 2000; }
    else return null;
    if (y < 2000 || y > 2100 || m < 1 || m > 12 || d < 1 || d > new Date(y, m, 0).getDate()) return null;
    const p = n => String(n).padStart(2, "0");
