  },
  // visitors sorted latest entry first, optional project filter, optional grouping by project.
  // Each visitor row is a copy with _p (project) and _b (badges html) ready for the page.
  arrange(list, ov, projectFilter, group, collapsed) {
    const want = projectFilter === "__none__" ? "" : projectFilter;
    let items = [];
    for (const v of list) {
      const r = ov[v.dbid];
      const project = (r && r.project) || "";
      if (projectFilter && project !== want) continue;
      items.push({ last: (r && r.last_entry) || "", project, row: Object.assign({}, v, { _p: project || "—", _b: Kav1.extras.badgesHtml(r) }) });
    }
    items.sort((a, b) => (a.last < b.last ? 1 : a.last > b.last ? -1 : 0));
    if (!group) return items.map(i => i.row);
    const groups = new Map();
    items.forEach(i => {
      if (!groups.has(i.project)) groups.set(i.project, []);
      groups.get(i.project).push(i.row);
    });
    const out = [];
    groups.forEach((members, k) => {
      const key = k || "__none__";
      out.push({ __g: true, key, title: k || "ללא פרויקט", count: members.length, folded: !!collapsed[key] });
      if (!collapsed[key]) members.forEach(m => out.push(m));
    });
    return out;
  },
  projects(ov) {
    const set = new Set();
    Object.values(ov).forEach(r => { if (r.project) set.add(r.project); });
    return [...set].sort();
  },
  // visitors with an expired / expiring / unreadable expiry, soonest first
  alerts(list, ov) {
    const out = [];
    list.forEach(v => {
      const r = ov[v.dbid]; if (!r) return;
      [["אישור", r.approval], ['סב"ט', r.classification]].forEach(([title, info]) => {
        if (info && info.status !== "ok") out.push({ v, title, info, days: info.days === null ? 9e9 : info.days, project: r.project });
      });
    });
    return out.sort((a, b) => a.days - b.days);
  },
};

