// take the well-known keys out of the free list so they are edited once, in their own fields;
// dates that cannot be read stay in the free list exactly as typed
extractManaged(v) {
  const ALIASES = {
    project: ["פרויקט", "פרויקטים", "project", "projects"],
    infosec: ["אבטחת מידע"],
    approval: ["תוקף אישור", "תאריך תום אישור"],
    cls: ['תוקף סב"ט', "תוקף סב״ט", "תוקף סיווג", "תוקף סיווג בטחוני"],
  };
  const props = Object.assign({}, v.properties || {});
  // aliases are in order of preference: the first one that holds a value wins
  const find = (field) => {
    const keys = Object.keys(props);
    const hit = (a) => keys.filter(k => k.trim() === a || k.trim().toLowerCase() === a);
    for (const a of ALIASES[field]) {
      const k = hit(a).find(x => String(props[x] == null ? "" : props[x]).trim() !== "");
      if (k !== undefined) return k;
    }
    for (const a of ALIASES[field]) { const k = hit(a)[0]; if (k !== undefined) return k; }   // present but empty
    return undefined;
  };
  const o = this.ov[v.dbid] || {};
  const iso = { approval: (o.approval && o.approval.date) || null, cls: (o.classification && o.classification.date) || null };
  for (const field of ["project", "infosec", "approval", "cls"]) {
    const k = find(field);
    if (k === undefined) continue;
    const val = String(props[k] == null ? "" : props[k]).trim();
    if ((field === "approval" || field === "cls") && !iso[field]) continue;   // unreadable date: leave it in the free list
    this.mfKeys[field] = k;
    if (field === "project") this.mf.project = val;
    else if (field === "infosec") this.mf.infosec = val;
    else if (field === "approval") this.mf.approval = Kav1.extras.fmtDate(iso.approval);
    else { this.mf.hasCls = true; this.mf.cls = Kav1.extras.fmtDate(iso.cls); }
    delete props[k];
  }
  return props;
},
